 }

+// onError is typed against Error, so anything else is wrapped with the original kept as its cause.
+function toError(thrown: unknown): Error {
+  if (thrown instanceof Error) return thrown;
+  const message = typeof thrown === 'string' ? thrown : describeRejection(thrown);
+  return new Error(message, {cause: thrown});
+}
